const { feishu_wiki } = require('./dist/channels/feishu/feishu-wiki.js');
(async () => {
  const r = await feishu_wiki({ action: 'get', token: 'WM3aw2TV8iuksmkMSYtcFYErnxh' });
  console.log(JSON.stringify(r, null, 2));
})();
"

cd ~/.openclaw && node -e "
const { feishu_wiki } = require('./dist/plugins/feishu-wiki/index.js');
" 2>&1 || find ~/.openclaw -name '*.js' -path '*/feishu*' 2>/dev/null | head -20

